const APPLE = '<svg width="34" height="34" viewBox="0 0 34 34"><path d="M17 9c-3-3-11-2-11 7 0 7 5 13 8 13 1.5 0 2-1 3-1s1.5 1 3 1c3 0 8-6 8-13 0-9-8-10-11-7z" fill="#E86A5A" stroke="#241F2E" stroke-width="2"/><path d="M17 9c0-3 1-5 3-6" stroke="#241F2E" stroke-width="2" fill="none" stroke-linecap="round"/><path d="M19 5c3-2 6-1 7 0-2 2-5 2-7 0z" fill="#8FD3B4" stroke="#241F2E" stroke-width="1.6"/></svg>';
