const ABC_FA = [['آ', 'آب', 'drop'], ['ب', 'بادکنک', 'balloon'], ['پ', 'پروانه', 'butterfly'], ['ت', 'توپ', 'ball'], ['ج', 'جوجه', 'chick'], ['د', 'درخت', 'tree'], ['س', 'سیب', 'apple'], ['ش', 'شمع', 'candle'], ['ک', 'کتاب', 'book'], ['گ', 'گل', 'flower'], ['م', 'ماه', 'moon'], ['ن', 'نازو', 'nazo']];
const ABC_EN = [['A', 'Apple', 'apple'], ['B', 'Ball', 'ball'], ['C', 'Candle', 'candle'], ['D', 'Drop', 'drop'], ['F', 'Flower', 'flower'], ['M', 'Moon', 'moon'], ['N', 'Nazo', 'nazo'], ['T', 'Tree', 'tree']];
let abcSet = 'fa', abcSel = 1; const abcSeen = new Set(store.get('abcSeen', []));
const picSvg = (k, s) => k === 'nazo' ? `<span style="width:${s}px;display:block">${nazo(G.color, G.wear)}</span>` : `<svg width="${s}" height="${s}" viewBox="0 0 100 100" aria-hidden="true">${PIC[k]}</svg>`;
function abcHtml() {
  const set = abcSet === 'fa' ? ABC_FA : ABC_EN, cur = set[Math.min(abcSel, set.length - 1)], en = abcSet === 'en';
  return `<div class="row" style="justify-content:space-between"><p class="t2" style="font-size:24px">${en ? 'جزیره‌ی ABC' : 'باغ حرف‌ها'}</p>
    <div class="seg" style="box-shadow:none;background:#fff;padding:3px"><button data-set="fa" aria-selected="${!en}" style="min-height:38px;padding:0 12px;font-size:14px">الفبا</button><button data-set="en" aria-selected="${en}" style="min-height:38px;padding:0 12px;font-size:14px;font-family:var(--en)">ABC</button></div></div>
   <div class="card" style="display:grid;grid-template-columns:auto 1fr;gap:14px;align-items:center;padding:16px 18px;min-height:178px">
    <div style="display:grid;justify-items:center;gap:6px"><span class="abcbig" style="font-size:110px;line-height:1;font-weight:900;color:var(--sky-ink);${en ? 'font-family:var(--en)' : ''};-webkit-text-stroke:2px var(--sky-ink);animation:trace 1.2s var(--ease) both" key="${cur[0]}">${cur[0]}</span></div>
    <div style="display:grid;justify-items:center;gap:6px;text-align:center">${picSvg(cur[2], 96)}<p class="t2" style="${en ? 'font-family:var(--en)' : ''}">${en ? cur[0] + ' is for ' + cur[1] : cur[0] + ' مثل ' + cur[1]}</p>
     <button class="btn sm" data-hear style="width:auto;padding:0 16px;background:var(--sky-soft);color:var(--sky-ink);box-shadow:none">${ic('spk', 18)}<span style="font-size:14px">بشنو</span></button></div></div>
   <div style="display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px">${set.map((l, i) => `<button class="opt ${i === abcSel ? 'yes' : ''}" data-l="${i}" style="min-height:${en ? 82 : 72}px;font-size:30px;font-weight:900;position:relative;${en ? 'font-family:var(--en)' : ''}">${l[0]}${abcSeen.has(abcSet + l[0]) ? `<span style="position:absolute;top:6px;inset-inline-end:6px">${ic('star', 14, '#E0A52A')}</span>` : ''}</button>`).join('')}</div>
   ${tabs(KTABS, 1)}`;
}
function paintAbc() { view('phAbc', abcHtml()) }
function abcEvents() {
  phones.phAbc.addEventListener('click', e => {
    const s = e.target.closest('[data-set]'); if (s) { abcSet = s.dataset.set; abcSel = 0; pop(); patch('phAbc', abcHtml()); return }
    if (e.target.closest('[data-hear]')) { const set = abcSet === 'fa' ? ABC_FA : ABC_EN, c = set[abcSel]; tone(440, .12); tone(550, .12, 'sine', .05, .14); toast((abcSet === 'fa' ? `«${c[0]}» مثل «${c[1]}»` : `“${c[0]}” is for “${c[1]}”`), 'spk'); return }
    const b = e.target.closest('[data-l]'); if (!b) return; abcSel = +b.dataset.l; const set = abcSet === 'fa' ? ABC_FA : ABC_EN;
    abcSeen.add(abcSet + set[abcSel][0]); store.set('abcSeen', [...abcSeen]); tone(500 + abcSel * 30, .1, 'triangle', .04); patch('phAbc', abcHtml());
    if (abcSeen.size >= 3) complete(4, b);
  });
}

/* ================= 6 WATCH: three worlds ================= */
const WORLDS = [['feelopia', 'فیلوپیا', 'دنیای درونت: احساس‌ها و آرامش', 'rose', 'احساس‌های بزرگ و پرسروصدا', '#F8DFE9', '#DF9BB7'], ['zivania', 'زیوانیا', 'دنیای بیرون: طبیعت و دوست‌ها', 'mint', 'یه خونه برای جغد', '#DBF0E6', '#8FD3B4'],
['avanian', 'آوانیان', 'ریشه‌ها، افسانه‌ها و دل‌های شجاع', 'peach', 'شب فانوس‌ها', '#FCE4D2', '#E99A63'], ['skills', 'مهارت‌های زندگی', 'درس‌های کوچک زندگی', 'sky', 'بستن بند کفش', '#DEEAFA', '#9CC0EC']];
const TALK = { feelopia: 'امشب بپرسید: «آخرین باری که احساس بزرگی داشتی کی بود؟»', zivania: 'امشب با هم از پنجره دنبال یک پرنده بگردید.', avanian: 'امشب یک فانوس کاغذی ساده با هم بسازید.', skills: 'فردا صبح بگذارید خودش بند کفشش را امتحان کند.' };
let playing = null, prog = 0, playT = null; const watched = new Set(store.get('watched', []));
function scene(w) {
  return `<svg viewBox="0 0 360 200" width="100%" style="display:block;border-radius:18px;background:${w[5]}" aria-hidden="true">
   <circle cx="300" cy="44" r="22" fill="#FFD66E" opacity=".9"/><g style="animation:drift 9s linear infinite"><path d="M40 60h46a14 14 0 000-28 20 20 0 00-38-4A16 16 0 0040 60z" fill="#fff"/></g>
   <path d="M0 150 Q90 110 180 145 T360 135 V200 H0z" fill="${w[6]}" opacity=".55"/><path d="M0 170 Q120 140 240 168 T360 160 V200 H0z" fill="${w[6]}"/>
   ${w[0] === 'zivania' ? '<rect x="250" y="96" width="12" height="60" rx="4" fill="#B57B4B"/><circle cx="256" cy="88" r="30" fill="#4FA37E"/>' : w[0] === 'avanian' ? '<g fill="#FFD66E" stroke="#241F2E" stroke-width="2"><rect x="230" y="70" width="20" height="28" rx="6"/><rect x="270" y="50" width="20" height="28" rx="6"/></g>' : w[0] === 'skills' ? '<path d="M240 140h60l6 14h-72z" fill="#5B93CF" stroke="#241F2E" stroke-width="3"/>' : '<g fill="#DF7FA5"><circle cx="250" cy="120" r="8"/><circle cx="270" cy="105" r="6"/><circle cx="288" cy="122" r="7"/></g>'}
   <g style="animation:walk 3s ease-in-out infinite;transform-origin:120px 150px"><g transform="translate(86 78) scale(.6)">${nazo(G.color, G.wear).replace(/<svg[^>]*>/, '').replace('</svg>', '')}</g></g></svg>`;
}
function watchHtml() {
  if (playing) {
    const w = WORLDS.find(x => x[0] === playing), end = prog >= 100;
    return `<div class="row">${`<button data-back style="width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center">${ic('fwd', 20)}</button>`}<div><p class="cp" style="font-weight:700">${w[1]}، قسمت ۲</p><p class="h1" style="font-weight:900">${w[4]}</p></div></div>
     <div style="background:#1B1724;border-radius:24px;padding:10px;display:grid;gap:10px">${scene(w)}<div class="bar" style="background:#3A3446"><i style="width:${prog}%;background:${w[6]}"></i></div>
      <div class="row" style="justify-content:space-between;color:#fff;padding:0 6px 4px"><span class="cp" style="color:#CFC8DE">${faN(Math.round(prog / 100 * 7))}:۰۰ / ۷:۰۰</span><span style="width:48px;height:48px;border-radius:50%;background:#fff;color:#1B1724;display:grid;place-items:center">${ic(end ? 'tick' : 'pause', 22)}</span></div></div>
     ${end ? `<div class="card" style="background:var(--${w[3]}-soft);box-shadow:none;display:grid;gap:6px"><p class="h1" style="font-weight:900;color:var(--${w[3]}-ink)">قسمت با آرامش تموم شد</p><p class="sb" style="color:var(--${w[3]}-ink)">برای مامان و بابا: ${TALK[w[0]]}</p></div><button class="btn" data-back>یه دنیای دیگه</button>` :
        `<div class="card" style="display:grid;gap:4px"><p class="cp" style="font-weight:700">بدون تبلیغ، بدون پخش خودکار قسمت بعد</p><p class="sb">وقتی قسمت تموم بشه، نازو یه پیشنهاد آروم می‌ده.</p></div>`}
     ${tabs(KTABS, 2)}`;
  }
  return `<p class="d1" style="font-size:28px">تماشا</p>
   <div class="card" style="padding:14px;display:flex;gap:12px;align-items:center">${sq('film', 'var(--sun-soft)', 'var(--sun-ink)', 48)}<div class="grow"><p class="h1" style="font-weight:900">۱۵٬۰۰۰ دقیقه قصه</p><p class="cp">در سه دنیا، به‌اضافه‌ی مهارت‌های زندگی</p></div></div>
   ${WORLDS.map(w => `<button class="card" data-w="${w[0]}" style="display:flex;gap:12px;align-items:center;text-align:start;padding:12px;width:100%">
     <span style="width:76px;height:76px;min-width:76px;border-radius:18px;background:${w[5]};display:grid;place-items:end center;overflow:hidden;position:relative">${w[0] === 'skills' ? `<span style="align-self:center;color:var(--sky-ink)">${ic('star', 34)}</span>` : `<span style="width:56px;margin-bottom:-6px">${nazo(w[3] === 'peach' ? 'peach' : w[3], '')}</span>`}</span>
     <span class="grow"><span class="h1" style="display:block;font-weight:900">${w[1]}</span><span class="cp" style="display:block">${w[2]}</span>${watched.has(w[0]) ? `<span class="pill" style="background:var(--mint-soft);color:var(--mint-ink);margin-top:4px;font-size:12px">${ic('tick', 13)}دیدی</span>` : ''}</span>
     <span style="width:44px;height:44px;min-width:44px;border-radius:50%;background:var(--${w[3]}-soft);color:var(--${w[3]}-ink);display:grid;place-items:center">${ic('play', 20)}</span></button>`).join('')}
   <div class="row" style="background:var(--lilac-soft);border-radius:18px;padding:10px 14px;color:var(--lilac-ink)">${ic('moon', 20)}<span class="sb" style="color:var(--lilac-ink);font-weight:700">زمان امروز رو مامان و بابا تعیین می‌کنن</span></div>
   ${tabs(KTABS, 2)}`;
}
function paintWatch() { view('phWatch', watchHtml()) }
function watchEvents() {
  phones.phWatch.addEventListener('click', e => {
    if (e.target.closest('[data-back]')) { clearInterval(playT); playing = null; pop(); patch('phWatch', watchHtml()); return }
    const w = e.target.closest('[data-w]'); if (!w) return; playing = w.dataset.w; prog = 0; pop(); patch('phWatch', watchHtml());
    clearInterval(playT); playT = setInterval(() => {
      prog = Math.min(100, prog + 4); const bar = $('.bar>i', phones.phWatch); if (bar) bar.style.width = prog + '%';
      const t = $('.view .cp[style*="CFC8DE"]', phones.phWatch); if (t) t.textContent = faN(Math.round(prog / 100 * 7)) + ':۰۰ / ۷:۰۰';
      if (prog >= 100) { clearInterval(playT); watched.add(playing); store.set('watched', [...watched]); chime(); patch('phWatch', watchHtml()); if (watched.size >= 2) complete(5, phones.phWatch) }
    }, 160);
  });
}

/* ================= 7 FAMILY: two phones, one loop ================= */
const F = { step: 0, coins: 120, save: 40, give: 10, praise: '', note: '' };
const PRAISE = ['آفرین، پشتکار داشتی!', 'بهت افتخار می‌کنم', 'چه مرتب!'];
const NOTES = [['heart', 'دوستت دارم', 'var(--rose-soft)', 'var(--rose-ink)'], ['star', 'تو بهترینی', 'var(--sun-soft)', 'var(--sun-ink)'], ['smile', 'امروز خوشحالم', 'var(--mint-soft)', 'var(--mint-ink)'], ['moon', 'شب بخیر', 'var(--lilac-soft)', 'var(--lilac-ink)']];
function jar(v, lab, col, ink, id) {
  const h = Math.min(66, Math.round(v / 3.2) + 6);
  return `<div style="display:grid;justify-items:center;gap:2px"><svg width="78" height="92" viewBox="0 0 84 100" aria-hidden="true"><rect x="26" y="4" width="32" height="10" rx="4" fill="#C2854F" stroke="#241F2E" stroke-width="3"/><path d="M14 20h56v62a12 12 0 01-12 12H26a12 12 0 01-12-12z" fill="#fff" stroke="#241F2E" stroke-width="3"/><clipPath id="j${id}"><path d="M14 20h56v62a12 12 0 01-12 12H26a12 12 0 01-12-12z"/></clipPath><rect clip-path="url(#j${id})" x="14" y="${94 - h}" width="56" height="80" fill="${col}" style="transition:y .6s var(--spring)"/></svg><b class="h1" style="color:${ink};font-weight:900">${faN(v)}</b><span class="cp" style="font-weight:800">${lab}</span></div>`;
}
function kidHtml() {
  const s = F.step;
  const task = s >= 3 ? `<div class="card" style="display:grid;gap:10px;${s === 3 ? 'box-shadow:0 0 0 3px var(--rose-deep),var(--sh)' : ''}"><div class="row">${sq('heart', 'var(--rose-soft)', 'var(--rose-ink)', 44)}<div><p class="h1" style="font-weight:900">حرف دلم برای مامان</p><p class="cp">یه تصویر انتخاب کن و بفرست</p></div></div>
      ${F.note ? `<div class="row" style="background:var(--mint-soft);border-radius:16px;padding:10px 12px;color:var(--mint-ink);font-weight:800">${ic('tick', 20)}فرستادی! مامان دیدش.</div>` : `<div class="g2" style="gap:8px">${NOTES.map((n, i) => `<button class="opt" data-note="${i}" style="min-height:64px;flex-direction:row;gap:8px;background:${n[2]};color:${n[3]};box-shadow:0 4px 0 rgba(0,0,0,.08)">${ic(n[0], 22)}<span style="font-size:14.5px">${n[1]}</span></button>`).join('')}</div>`}</div>`
    : `<div class="card" style="display:grid;gap:12px;${s === 0 ? 'box-shadow:0 0 0 3px var(--lilac-deep),var(--sh)' : ''}"><div class="row">${sq('book', 'var(--lilac-soft)', 'var(--lilac-ink)', 48)}<div class="grow"><p class="h1" style="font-weight:900">تموم کردن مشق‌هام</p><p class="cp">روزهای مدرسه</p></div><span class="pill" style="background:var(--peach-soft);color:var(--peach-ink);font-size:14px">${COIN(16)}۴۰</span></div>
      ${s === 0 ? `<button class="btn" data-done>${ic('check', 22)}انجامش دادم!</button>` : s === 1 ? `<div class="row" style="background:var(--sun-soft);color:var(--sun-ink);border-radius:16px;padding:12px;font-weight:800">${ic('clock', 22)}<span>منتظر تأیید مامان…</span></div>` : `<div class="row" style="background:var(--mint-soft);color:var(--mint-ink);border-radius:16px;padding:12px;font-weight:800">${ic('tick', 22)}<span>مامان تأیید کرد! +۴۰ سکه${F.praise ? '<br><small style="font-weight:700">«' + F.praise + '»</small>' : ''}</span></div>`}</div>`;
  return `<div class="row" style="justify-content:space-between"><p class="d1" style="font-size:28px">جایزه‌های من</p><span class="pill" style="background:var(--peach-soft);color:var(--peach-ink);font-size:16px;padding:6px 12px">${COIN(20)}<b class="num">${faN(F.coins)}</b></span></div>
   ${task}
   <div class="card" style="display:grid;gap:10px;${s === 2 ? 'box-shadow:0 0 0 3px var(--mint-deep),var(--sh)' : ''}"><p class="h1" style="font-weight:900">سه قلک من</p>
    <div style="display:flex;justify-content:space-around;align-items:flex-end">${jar(F.coins, 'خرج', '#F7B267', 'var(--peach-ink)', 'a')}${jar(F.save, 'پس‌انداز', '#8FD3B4', 'var(--mint-ink)', 'b')}${jar(F.give, 'بخشش', '#EFA7C4', 'var(--rose-ink)', 'c')}</div>
    <div class="g2" style="gap:8px"><button class="btn sm" data-jar="save" style="background:var(--mint-soft);color:var(--mint-ink);box-shadow:0 4px 0 #B5DFCB" ${s < 2 ? 'disabled' : ''}>${ic('jar', 18)}پس‌انداز ۱۰</button><button class="btn sm" data-jar="give" style="background:var(--rose-soft);color:var(--rose-ink);box-shadow:0 4px 0 #EBC3D3" ${s < 2 ? 'disabled' : ''}>${ic('heart', 18)}بخشش ۱۰</button></div></div>
   ${s >= 3 && !F.note ? '' : `<div class="card" style="padding:12px 14px;display:grid;gap:8px"><div class="row">${sq('gift', 'var(--rose-soft)', 'var(--rose-ink)', 40)}<div class="grow"><p class="h1" style="font-weight:900;font-size:16px">هدف پس‌انداز: کتاب قصه</p><p class="cp">${faN(Math.min(F.save, 220))} از ۲۲۰ سکه</p></div></div><div class="bar"><i style="width:${Math.min(100, Math.round(F.save / 220 * 100))}%;background:var(--mint)"></i></div></div>`}
   ${tabs(KTABS, 3)}`;
}
function parHtml() {
  const s = F.step;
  return `<div class="row" style="justify-content:space-between"><p class="cp" style="font-weight:700">سه‌شنبه ۷ مهر</p><div class="row" style="gap:8px">${['cal', 'sos', 'bell'].map(i => `<span style="width:40px;height:40px;border-radius:13px;background:#fff;display:grid;place-items:center;color:var(--ink-2)">${ic(i === 'sos' ? 'smile' : i, 20)}</span>`).join('')}</div></div>
   <p class="d1" style="font-size:30px">عصر بخیر</p>
   <div class="row" style="gap:8px"><span class="chip on" style="min-height:40px">آریا، ۷ ساله</span><span class="chip" style="min-height:40px">سام، ۴ ساله</span></div>
   ${s === 1 ? `<div class="ping">${sq('check', 'var(--lilac-soft)', 'var(--lilac-ink)', 40)}<div><p class="h1" style="font-weight:900;font-size:15px">آوانیان، همین حالا</p><p class="cp" style="color:var(--ink-2)">آریا «تموم کردن مشق‌هام» رو انجام داد.</p></div></div>` : ''}
   ${F.note && s >= 3 ? `<div class="card" style="background:var(--rose-soft);box-shadow:0 0 0 3px var(--rose-deep);display:flex;gap:12px;align-items:center;animation:ping .6s var(--spring)"><span style="width:58px;height:58px;min-width:58px;border-radius:18px;background:#fff;display:grid;place-items:center;color:${NOTES[F.note - 1][3]}">${ic(NOTES[F.note - 1][0], 32)}</span><div><p class="h1" style="font-weight:900;color:var(--rose-ink)">حرف دل آریا</p><p class="sb" style="color:var(--rose-ink)">«${NOTES[F.note - 1][1]}»</p></div></div>` : ''}
   <div class="card" style="display:grid;gap:12px;${s === 1 ? 'box-shadow:0 0 0 3px var(--lilac-deep),var(--sh)' : ''}">
    <div class="row" style="justify-content:space-between"><p class="h1" style="font-weight:900">کارهای امروز آریا</p><span class="cp" style="color:var(--lilac-ink);font-weight:800">همه و افزودن</span></div>
    <div class="row"><div class="grow"><p class="h1">${faN(s >= 2 ? 1 : 0)} از ۳ کار انجام شد</p><p class="cp">${s === 1 ? '۱ مورد منتظر تأیید شماست' : s >= 2 ? 'عالی پیش می‌ره' : 'هنوز کاری تموم نشده'}</p></div>
     <svg width="46" height="46" viewBox="0 0 46 46"><circle cx="23" cy="23" r="18" fill="none" stroke="#E7E3F0" stroke-width="6"/><circle cx="23" cy="23" r="18" fill="none" stroke="var(--mint-deep)" stroke-width="6" stroke-linecap="round" stroke-dasharray="${s >= 2 ? 37.7 : 0} 113" transform="rotate(-90 23 23)"/></svg></div>
    <div class="row" style="background:var(--app);border-radius:16px;padding:10px 12px">${sq('book', 'var(--lilac-soft)', 'var(--lilac-ink)', 40)}<div class="grow"><p class="h1" style="font-size:16px">تموم کردن مشق‌هام</p><p class="cp">روزهای مدرسه، ۴۰ سکه</p></div></div>
    ${s === 1 ? `<div class="g2" style="gap:8px"><button class="btn sm" data-ok style="background:var(--mint);color:#0F4430;box-shadow:0 4px 0 #5FAF8A">${ic('check', 18)}تأیید</button><button class="btn sm white" data-no>هنوز نه</button></div>` :
      s === 2 && !F.praise ? `<p class="cp" style="font-weight:800">یه جمله‌ی تشویق بفرستید؟</p><div style="display:flex;flex-wrap:wrap;gap:6px">${PRAISE.map((p, i) => `<button class="chip" data-praise="${i}" style="background:var(--mint-soft);color:var(--mint-ink);min-height:40px">${p}</button>`).join('')}</div>` :
        s >= 2 ? `<div class="row" style="color:var(--mint-ink);font-weight:800">${ic('tick', 20)}تأیید شد${F.praise ? '، «' + F.praise + '»' : ''}</div>` : `<p class="cp">وقتی آریا کاری رو تموم کنه، اینجا تأییدش می‌کنید.</p>`}
   </div>
   <div class="card" style="display:flex;gap:12px;align-items:center;padding:12px 16px">${moodFace('sunny', 44)}<div><p class="h1" style="font-weight:900">حال امروز</p><p class="cp">آریا صبح گفت باتری‌اش «پر» است</p></div></div>
   ${F.note && s >= 3 ? '' : `<div class="card" style="background:var(--peach-soft);box-shadow:none;padding:12px 16px"><p class="h1" style="font-weight:900;color:var(--peach-ink)">برای امشب</p><p class="sb" style="color:var(--peach-ink)">بپرسید: «امروز چه چیزی تو را خنداند؟»</p></div>`}
   ${tabs(PTABS, 0, s === 1 ? { badge: 0, n: 1 } : {})}`;
}
function paintFamily() {
  view('phKid', kidHtml()); view('phPar', parHtml());
  $$('#flow span').forEach((sp, i) => { sp.classList.toggle('on', i === Math.min(F.step, 3)); sp.classList.toggle('ok', i < F.step || (i === 3 && F.note)) });
}
function duoShow(d) { $$('.dslot').forEach(x => x.classList.toggle('act', x.dataset.d === d)); $$('#duoSeg button').forEach(b => b.setAttribute('aria-selected', b.dataset.d === d)) }
const narrow = () => matchMedia('(max-width:760px)').matches;
function familyEvents() {
  $('#duoSeg').addEventListener('click', e => { const b = e.target.closest('button'); if (b) { duoShow(b.dataset.d); pop() } });
  phones.phKid.addEventListener('click', async e => {
    if (e.target.closest('[data-done]')) { F.step = 1; pop(); paintFamily(); if (narrow()) { await sleep(900); duoShow('par') } return }
    const j = e.target.closest('[data-jar]');
    if (j && F.coins >= 10) { F.coins -= 10; F[j.dataset.jar] += 10; tone(740, .08, 'triangle'); if (F.step === 2) { F.step = 3; complete(6, j) } paintFamily(); return }
    const n = e.target.closest('[data-note]');
    if (n) { F.note = +n.dataset.note + 1; chime(); paintFamily(); if (!G.heart) { G.heart = 1; save(); earn(10, n, tx(['حرف دلم فرستاده شد! +۱۰ سکه', 'Heart note sent! +10 coins'])) } if (narrow()) { await sleep(900); duoShow('par') } }
  });
  phones.phPar.addEventListener('click', async e => {
    if (e.target.closest('[data-ok]')) { F.step = 2; F.coins += 40; chime(); paintFamily(); const r = e.target.closest('[data-ok]'); if (narrow()) { await sleep(1300); duoShow('kid') } return }
    if (e.target.closest('[data-no]')) { F.step = 0; soft(); toast(tx(['آریا پیام گرفت: «یه کم دیگه، تقریباً تمومه!»', 'Arya got: “Almost there, a little more!”']), 'chat'); paintFamily(); if (narrow()) { await sleep(900); duoShow('kid') } return }
    const p = e.target.closest('[data-praise]'); if (p) { F.praise = PRAISE[+p.dataset.praise]; pop(); paintFamily() }
  });
}

/* ================= 8 PULSE: the week's garden ================= */
const WEEK = [['ش', 'شنبه', 'sunny', 'آفتابی', '۲ کار انجام داد، فیلوپیا دید'], ['ی', 'یکشنبه', 'calm', 'آرام', '۱ کار، جزیره‌ی عددها'], ['د', 'دوشنبه', 'wobbly', 'ابری', 'کمتر بازی کرد، زود خوابید'], ['س', 'سه‌شنبه', 'sunny', 'آفتابی', '۳ کار، حرف دلم فرستاد'],
['چ', 'چهارشنبه', 'calm', 'آرام', 'قصه‌ی شب، ۲ کلمه‌ی احساس تازه'], ['پ', 'پنجشنبه', 'sunny', 'آفتابی', 'کلاس قصه‌گویی، ۲ کار'], ['ج', 'جمعه', 'sunny', 'آفتابی', 'با خانواده بیرون رفت']];
const STARTERS = ['بپرسید: «امروز چه چیزی تو را خنداند؟»', 'بپرسید: «اگر نازو امروز با تو بود، کجا می‌بردیش؟»', 'بپرسید: «سخت‌ترین کار امروز چی بود؟ چطور انجامش دادی؟»'];
function flower(id, sel) {
  const m = MOOD[id]; let pet = ''; for (let i = 0; i < 5; i++) { const a = i / 5 * Math.PI * 2; pet += `<circle cx="${(19 + Math.cos(a) * 7.5).toFixed(1)}" cy="${(17 + Math.sin(a) * 7.5).toFixed(1)}" r="6.2" fill="${m.c}" stroke="${m.ink}" stroke-width="1.2"/>` }
  return `<svg width="38" height="58" viewBox="0 0 38 58" aria-hidden="true" style="${sel ? 'transform:scale(1.18)' : ''};transition:transform .3s var(--spring)"><path d="M19 56V26" stroke="#4FA37E" stroke-width="3" stroke-linecap="round"/><path d="M19 43 q-10 -2 -12 -10 q10 1 12 10z" fill="#8FD3B4"/>${pet}<circle cx="19" cy="17" r="5" fill="#FFE9A8" stroke="${m.ink}" stroke-width="1.2"/></svg>`;
}
let pDay = 3, pStart = 0; const pSeen = new Set();
function pulseHtml() {
  const d = WEEK[pDay];
  return `<div class="row">${sq('fwd', '#fff', 'var(--ink)', 40)}<p class="t2" style="font-size:24px">نبض هفته</p><span class="pill" style="margin-inline-start:auto;background:var(--mint-soft);color:var(--mint-ink)">از روی همین هفته</span></div>
   <div class="card" style="padding:14px 12px"><p class="cp" style="font-weight:700;margin-bottom:6px;padding-inline:4px">باغچه‌ی این هفته، روی هر گل بزن</p>
    <div style="display:flex;justify-content:space-between">${WEEK.map((w, i) => `<button data-day="${i}" style="display:grid;justify-items:center;gap:2px;padding:4px 2px;border-radius:14px;${i === pDay ? 'background:var(--lilac-soft)' : ''}">${flower(w[2], i === pDay)}<span class="cp" style="font-weight:800;${i === pDay ? 'color:var(--lilac-ink)' : ''}">${w[0]}</span></button>`).join('')}</div>
    <div class="row" style="background:var(--app);border-radius:16px;padding:10px 12px;margin-top:8px" key="${pDay}">${moodFace(d[2], 40)}<div><p class="h1" style="font-weight:900;font-size:16px">${d[1]}: ${d[3]}</p><p class="cp">${d[4]}</p></div></div></div>
   <div class="card" style="padding:14px 16px;display:grid;gap:8px"><div class="row" style="justify-content:space-between"><p class="h1" style="font-weight:900">علاقه‌ها، این هفته</p><span class="pill" style="background:var(--mint-soft);color:var(--mint-ink)">صبح‌ها شادتر از ماه پیش</span></div>
    ${[['قصه و کتاب', 72, 'var(--lilac)', '↑'], ['عدد و معما', 54, 'var(--mint)', ''], ['نقاشی', 42, 'var(--rose)', '']].map(r => `<div><div class="row" style="justify-content:space-between"><span class="sb" style="font-weight:700;color:var(--ink)">${r[0]}</span><span class="cp" style="font-weight:800">${faN(r[1])}٪ ${r[3] ? '<span style="color:var(--mint-ink)">بیشتر شد</span>' : ''}</span></div><div class="bar" style="height:8px"><i style="width:${r[1]}%;background:${r[2]}"></i></div></div>`).join('')}</div>
   <div class="card" style="background:var(--peach-soft);box-shadow:none;padding:14px 16px"><p class="h1" style="font-weight:900;color:var(--peach-ink)">یک سؤال برای امشب</p><p class="sb" style="color:var(--peach-ink)">${STARTERS[pStart]}</p><button data-next class="cp" style="font-weight:800;color:var(--peach-ink);text-decoration:underline;margin-top:2px">یکی دیگه</button></div>
   ${tabs(PTABS, 1)}`;
}
function paintPulse() { view('phPulse', pulseHtml()) }
function pulseEvents() {
  phones.phPulse.addEventListener('click', e => {
    const d = e.target.closest('[data-day]'); if (d) { pDay = +d.dataset.day; pSeen.add(pDay); tone(500 + pDay * 50, .08, 'triangle', .04); patch('phPulse', pulseHtml()); if (pSeen.size >= 3) complete(7, d); return }
    if (e.target.closest('[data-next]')) { pStart = (pStart + 1) % STARTERS.length; pop(); patch('phPulse', pulseHtml()) }
  });
}

/* ================= 9 CLASSES ================= */
const CLS = [['قصه‌گویی و نمایش عروسکی', 'art', 'خانه‌ی هنر کودک، ۱٫۲ کیلومتر', 'سن ۵ تا ۸', 'پنجشنبه ۱۷:۰۰', 'book', 'lilac', true], ['شنای کودک', 'sport', 'استخر پارک، ۲ کیلومتر', 'سن ۶ تا ۱۰', 'شنبه ۱۰:۰۰', 'swim', 'sky'],
['آزمایش‌های کوچک', 'sci', 'خانه‌ی علم، ۰٫۸ کیلومتر', 'سن ۷ تا ۱۰', 'دوشنبه ۱۶:۳۰', 'atom', 'mint'], ['ریتم و آواز', 'music', 'آموزشگاه نوا، ۱٫۵ کیلومتر', 'سن ۴ تا ۷', 'چهارشنبه ۱۷:۰۰', 'music', 'peach'], ['نقاشی با آبرنگ', 'art', 'کارگاه رنگ، ۰٫۶ کیلومتر', 'سن ۵ تا ۹', 'جمعه ۱۰:۳۰', 'palette', 'rose']];
const CF = [['all', 'همه'], ['art', 'هنر'], ['sport', 'ورزش'], ['sci', 'علم'], ['music', 'موسیقی']];
let cFilt = 'all', cBook = -1;
function clsHtml() {
  if (cBook >= 0) {
    const c = CLS[cBook]; let qr = ''; for (let i = 0; i < 49; i++) { const x = i % 7, y = (i / 7) | 0, on = ((x * 7 + y * 3 + cBook) * 5) % 3 === 0 || (x < 2 && y < 2) || (x > 4 && y < 2) || (x < 2 && y > 4); qr += `<rect x="${x * 10}" y="${y * 10}" width="9" height="9" rx="2" fill="${on ? '#241F2E' : 'transparent'}"/>` }
    return `<div class="row"><button data-cback style="width:44px;height:44px;border-radius:50%;background:#fff;display:grid;place-items:center">${ic('fwd', 20)}</button><p class="t2">رزرو شد!</p></div>
     <div class="card" style="display:grid;gap:12px;justify-items:center;text-align:center;border-top:8px solid var(--${c[6]})"><span style="width:84px">${nazo(G.color, G.wear, 'joy')}</span><p class="t2" style="font-size:21px">${c[0]}</p><p class="sb">${c[4]}، ${c[2]}</p>
      <div style="width:100%;border-top:2px dashed var(--line);margin:4px 0"></div><div class="row" style="width:100%;justify-content:space-between"><div style="text-align:start"><p class="cp">کودک</p><p class="h1" style="font-weight:900">آریا</p><p class="cp" style="margin-top:6px">کد بلیت</p><p class="h1" style="font-family:var(--en);letter-spacing:.1em">AV-${faN(4127 + cBook)}</p></div><svg width="92" height="92" viewBox="-4 -4 78 78" style="background:#fff;border-radius:12px"><g>${qr}</g></svg></div></div>
     <div class="card" style="padding:12px 16px"><div class="row" style="gap:8px;color:var(--mint-ink);font-weight:800">${ic('cal', 20)}به تقویم خانواده اضافه شد</div>
      <div style="display:grid;grid-template-columns:repeat(7,1fr);gap:4px;margin-top:10px;text-align:center">${WEEK.map((w, i) => `<span style="border-radius:12px;padding:6px 0;background:${c[4].startsWith(w[1]) ? 'var(--' + c[6] + '-soft)' : 'var(--app)'};font-weight:800;font-size:13px;color:${c[4].startsWith(w[1]) ? 'var(--' + c[6] + '-ink)' : 'var(--ink-3)'}">${w[0]}${c[4].startsWith(w[1]) ? '<i style="display:block;width:6px;height:6px;border-radius:50%;margin:3px auto 0;background:var(--' + c[6] + '-ink)"></i>' : ''}</span>`).join('')}</div></div>
     ${tabs(PTABS, 2)}`;
  }
  const list = CLS.map((c, i) => [c, i]).filter(([c]) => cFilt === 'all' || c[1] === cFilt);
  return `<div class="card" style="padding:12px 14px;display:flex;gap:12px;align-items:center">${sq('cal', 'var(--sky-soft)', 'var(--sky-ink)', 42)}<div class="grow"><p class="h1" style="font-weight:900;font-size:16px">تقویم کلاس‌ها و رویدادها</p><p class="cp">بعدی: بسکتبال کودکان، شنبه</p></div></div>
   <p class="d1" style="font-size:28px">کلاس‌های نزدیک شما</p>
   <div style="display:flex;gap:6px;flex-wrap:nowrap;overflow:hidden">${CF.map(f => `<button class="chip ${cFilt === f[0] ? 'on' : ''}" data-f="${f[0]}" style="min-height:40px;padding:0 14px">${f[1]}</button>`).join('')}</div>
   <p class="h1" style="font-weight:900">مناسب علاقه‌های آریا</p>
   ${list.slice(0, 4).map(([c, i]) => `<div class="card" style="display:flex;gap:12px;align-items:center;padding:12px 14px">${sq(c[5], 'var(--' + c[6] + '-soft)', 'var(--' + c[6] + '-ink)', 48)}<div class="grow"><p class="h1" style="font-weight:900;font-size:16px">${c[0]}${c[7] ? ' <span class="pill" style="background:var(--lilac-soft);color:var(--lilac-ink);font-size:11.5px;padding:1px 8px">علاقه به قصه</span>' : ''}</p><p class="cp">${c[2]}</p><p class="cp">${c[3]}، ${c[4]}</p></div><button class="btn sm" data-book="${i}" style="width:auto;padding:0 14px;min-height:42px;font-size:15px">رزرو</button></div>`).join('')}
   ${tabs(PTABS, 2)}`;
}
function paintCls() { view('phCls', clsHtml()) }
function clsEvents() {
  phones.phCls.addEventListener('click', e => {
    const f = e.target.closest('[data-f]'); if (f) { cFilt = f.dataset.f; pop(); patch('phCls', clsHtml()); return }
    const b = e.target.closest('[data-book]'); if (b) { cBook = +b.dataset.book; chime(); patch('phCls', clsHtml()); complete(8, b); return }
    if (e.target.closest('[data-cback]')) { cBook = -1; pop(); patch('phCls', clsHtml()) }
  });
}

/* ================= wardrobe + islands board ================= */
function paintCloset() {
  const m = $('#mirror'); if (!m) return;
  m.style.setProperty('--c-soft', `var(--${G.color === 'lilac' ? 'lilac' : G.color}-soft)`);
  m.innerHTML = nazo(G.color, G.wear);
  $('#colors').innerHTML = Object.keys(NZC).map(c => `<button aria-pressed="${G.color === c}" data-c="${c}" style="background:${NZC[c]}" aria-label="${c}"></button>`).join('');
  $('#walletN').textContent = N(G.coins);
  $('#items').innerHTML = WEAR.map(([id, nm, cost]) => {
    const own = G.owned.includes(id), on = G.wear === id;
    return `<button class="item ${own ? 'own' : ''} ${on ? 'on' : ''} ${!own && G.coins < cost ? 'poor' : ''}" data-w="${id}">${nazo(G.color, id)}<b>${tx(nm)}</b><small>${on ? tx(['پوشیده', 'Wearing']) : own ? tx(['بپوشان', 'Wear']) : COIN(14) + N(cost)}</small></button>`;
  }).join('');
  $$('[data-nazo]').forEach(s => { s.innerHTML = nazo(G.color, G.wear) });
}
function closetEvents() {
  $('#colors').addEventListener('click', e => { const b = e.target.closest('[data-c]'); if (!b) return; G.color = b.dataset.c; save(); pop(); paintCloset(); repaintPhones() });
  $('#items').addEventListener('click', e => {
    const b = e.target.closest('[data-w]'); if (!b) return; const [id, nm, cost] = WEAR.find(w => w[0] === b.dataset.w);
    if (G.owned.includes(id)) { G.wear = G.wear === id ? '' : id; save(); pop(); paintCloset(); repaintPhones(); return }
    if (G.coins < cost) { soft(); toast(tx([`${faN(cost - G.coins)} سکه‌ی دیگه لازم داری. یه ایستگاه دیگه رو تموم کن!`, `You need ${cost - G.coins} more coins. Finish another stop!`]), 'coin'); return }
    G.coins -= cost; G.owned.push(id); G.wear = id; save(); chime(); const r = b.getBoundingClientRect(); confetti(r.left + r.width / 2, r.top, 26);
    toast(tx([`نازو ${nm[0]} پوشید!`, `Nazo is wearing the ${nm[1].toLowerCase()}!`]), 'sparkle'); paintHud(); paintCloset(); repaintPhones();
  });
}
function islesHtml() {
  return ST.map((s, i) => `<button class="isle ${G.done[i] ? 'ok' : ''}" data-go="${s.id}" style="--c:${s.c}"><span class="dot">${G.done[i] ? ic('tick', 20) : N(i + 1)}</span><span><b>${tx(s.n)}</b><small>${G.done[i] ? tx(['تمام شد', 'Done']) : tx(['+۳۰ سکه', '+30 coins'])}</small></span></button>`).join('');
}
function paintIsles() { $$('.isles').forEach(x => x.innerHTML = islesHtml()) }
document.addEventListener('click', e => { const g = e.target.closest('.isle[data-go]'); if (g) { const sc = g.closest('.scrim'); if (sc) sc.remove(); pop(); go(g.dataset.go) } });

/* ================= HUD, journey sheet, finale ================= */
function paintHud() {
  $('#hudCoins').textContent = N(G.coins); $('#hudIsl').textContent = L ? doneCount() + '/9' : faN(doneCount()) + '/۹';
  $$('#navprog i').forEach((x, i) => { x.classList.toggle('on', !!G.done[i]); x.style.setProperty('--c', ST[i].c) });
  $$('[data-nazo]').forEach(s => { s.innerHTML = nazo(G.color, G.wear) });
}
function sheet(inner, cls) {
  const s = el('div', 'scrim ' + (cls || ''), `<div class="sheet" role="dialog" aria-modal="true"><span class="grab"></span>${inner}</div>`);
  s.addEventListener('click', e => { if (e.target === s || e.target.closest('[data-x]')) s.remove() });
  document.body.appendChild(s); const f = $('button,input', s); if (f) f.focus(); return s;
}
function journey() {
  const nx = G.done.indexOf(0);
  sheet(`<div class="shead">${nazo(G.color, G.wear)}<div><h3>${tx(['سفر تو در آوانیان', 'Your Avanian journey'])}</h3><p style="color:var(--ink-2);font-weight:700">${tx([`${faN(doneCount())} از ۹ ایستگاه، ${faN(G.coins)} سکه`, `${doneCount()} of 9 stops · ${G.coins} coins`])}</p></div><button class="ibtn x" data-x aria-label="close">${ic('x')}</button></div>
    <p style="color:var(--ink-2)">${tx(['هر ایستگاه یکی از امکانات واقعی اپ است. تمامش کن، سکه بگیر و در «کمد نازو» خرجش کن.', 'Each stop is a real feature of the app. Finish it, earn coins, and spend them in Nazo’s wardrobe.'])}</p>
    <div class="isles">${islesHtml()}</div>
    <div style="display:flex;gap:10px;flex-wrap:wrap">${nx >= 0 ? `<button class="btn" data-x id="jGo">${ic('play', 18)}${tx(['ایستگاه بعدی', 'Next stop'])}</button>` : ''}<button class="btn white" data-x id="jCloset">${ic('coin')}${tx(['کمد نازو', 'Wardrobe'])}</button><button class="btn white sm" id="jReset" style="margin-inline-start:auto">${tx(['از نو', 'Start over'])}</button></div>`);
  const g = $('#jGo'); if (g) g.addEventListener('click', () => go(ST[nx].id));
  $('#jCloset').addEventListener('click', () => go('closet'));
  $('#jReset').addEventListener('click', () => { if (!confirm(tx(['همه‌ی سکه‌ها و ایستگاه‌ها پاک شوند؟', 'Reset all coins and stops?']))) return; ['g', 'feelWords', 'abcSeen', 'watched', 'mapAt'].forEach(k => store.set(k, null)); location.reload() });
}
function finale() {
  if ($('.scrim.finale')) return;
  G.fin = 1; if (!G.owned.includes('crown')) G.owned.push('crown'); G.wear = 'crown'; save(); paintAll();
  confetti(innerWidth / 2, innerHeight / 3, 110); chime();
  const s = sheet(`<div style="display:grid;justify-items:center;gap:6px">${nazo(G.color, 'crown', 'joy')}<h3>${tx(['هر ۹ ایستگاه را رفتی!', 'You visited all 9 stops!'])}</h3><p style="color:var(--ink-2)">${tx(['حالا آوانیان را خوب می‌شناسی. برای گرفتن تاج طلایی نازو در اپ، جای خانواده‌تان را در فهرست انتظار نگه دارید.', 'Now you know Avanian well. To get Nazo’s golden crown in the app, save your family’s spot on the waitlist.'])}</p></div>
    <div class="cert"><b style="font-size:18px">${tx(['گواهی قهرمان سفر', 'Journey hero certificate'])}</b><input id="certName" maxlength="20" placeholder="${tx(['اسم کودکت', "Your child's name"])}" value="${esc(G.kid)}"><span style="font-weight:800;color:var(--ink-3)" id="certLine">${G.kid ? esc(G.kid) + tx([' و نازو منتظر روز انتشارند.', ' and Nazo are waiting for launch day.']) : ''}</span></div>
    <a class="btn" href="#join" data-x>${ic('star')}${tx(['جای خانواده‌تان را نگه دارید', "Save your family's spot"])}</a>`, 'finale');
  $('#certName', s).addEventListener('input', e => { G.kid = e.target.value.slice(0, 20); save(); $('#certLine', s).textContent = G.kid ? G.kid + tx([' و نازو منتظر روز انتشارند.', ' and Nazo are waiting for launch day.']) : '' });
}

