function liveEvents() {
  // FULL: only the private build has the whole prototype one tab away; the public site has the guided demo alone
  const FULL = !!$('#modeSeg');
  let view0 = 'kid', mode = 'demo', at = Math.min(store.get('demo', 0), DEMO.length - 1);
  const scr = $('#phReal .scr'), app = phones.phReal, card = $('#dcard');
  const load = () => { let f = $('iframe', scr); if (!f) { f = el('iframe'); f.title = 'Avanian'; f.setAttribute('loading', 'lazy'); scr.appendChild(f) } f.src = 'webapp/index.html?view=' + view0 };
  const paintCard = () => {
    const s = DEMO[at], par = s.ph === 'par', prev = L ? 'back' : 'fwd';
    card.innerHTML = `<div class="dtop"><span class="chip ${par ? 'par' : ''}">${ic(par ? 'user' : 'smile', 16)}${tx(par ? ['گوشی والد', 'Parent phone'] : ['گوشی کودک', 'Kid phone'])}</span><span class="dn num">${N(at + 1)} / ${N(DEMO.length)}</span></div>
      <div class="dbar"><i style="width:${(at + 1) / DEMO.length * 100}%"></i></div>
      <h3>${tx(s.t)}</h3><p>${tx(s.d)}</p>
      <div class="dbtns">${at ? `<button class="ibtn" data-d="prev" aria-label="${tx(['قبلی', 'Back'])}">${ic(L ? 'fwd' : 'back')}</button>` : ''}
      ${s.end ? (FULL ? `<button class="btn" data-d="full">${ic('phone')}${tx(['اپ کامل را باز کن', 'Open the full app'])}</button>` : `<a class="btn" href="#join">${ic('star')}${tx(['ثبت‌نام زودهنگام', 'Join the waitlist'])}</a>`) + `<button class="btn white" data-d="again">${tx(['دوباره', 'Again'])}</button>`
        : `<button class="btn ${s.hot ? 'white' : ''}" data-d="next">${tx(s.next || ['بعدی', 'Next'])}${ic(L ? 'back' : 'fwd', 18)}</button>`}</div>`;
  };
  const show = (dir = 1) => {
    const s = DEMO[at]; store.set('demo', at);
    const old = $('.dscr', app), n = el('div', 'dscr');
    n.innerHTML = `<img src="${DEMO_IMG[s.img]}" alt="" draggable="false">${s.ok ? `<div class="dok">${ic('tick', 22)}<span>تأیید شد، ۴۰ سکه رفت</span></div>` : ''}${s.hot ? `<button class="dhot" style="left:${s.hot[0]}px;top:${s.hot[1]}px;width:${s.hot[2]}px;height:${s.hot[3]}px" aria-label="${tx(s.t)}"></button>` : ''}`;
    app.appendChild(n);
    if (old && !RM) { n.animate([{ opacity: 0, transform: `translateX(${dir * (L ? 40 : -40)}px)` }, { opacity: 1, transform: 'none' }], { duration: 320, easing: 'cubic-bezier(.22,1,.36,1)' }); old.animate([{ opacity: 1 }, { opacity: 0 }], { duration: 220 }).finished.then(() => old.remove()); setTimeout(() => old.remove(), 400) }
    else if (old) old.remove();
    paintCard();
  };
  const go = d => { const n = at + d; if (n < 0 || n >= DEMO.length) return; at = n; pop(); show(d) };
  const finish = from => { chime(); if (!G.tour) { G.tour = 1; save(); earn(30, from, tx(['تور اپ تمام شد! +۳۰ سکه', 'App tour complete! +30 coins'])) } };
  const ripple = (x, y) => { if (RM) return; const r = el('i', 'dripple'); r.style.left = x + 'px'; r.style.top = y + 'px'; app.appendChild(r); setTimeout(() => r.remove(), 600) };
  app.addEventListener('click', async e => {
    if (mode !== 'demo') return;
    const k = +getComputedStyle(scr).getPropertyValue('--k') || 1, b = scr.getBoundingClientRect(), x = (e.clientX - b.left) / k, y = (e.clientY - b.top) / k;
    if (e.clientX || e.clientY) ripple(x, y);
    const h = e.target.closest('.dhot');
    if (!h) { const t = $('.dhot', app); if (t) { soft(); t.classList.remove('nudge'); void t.offsetWidth; t.classList.add('nudge') } return }
    const s = DEMO[at];
    if (s.img === 'par_home' && !s.ok) { const r = h.getBoundingClientRect(); confetti(r.left + r.width / 2, r.top, 24); chime() }
    go(1); if (DEMO[at].end) finish(h);
  });
  card.addEventListener('click', e => {
    const b = e.target.closest('[data-d]'); if (!b) return; const d = b.dataset.d;
    if (d === 'next') { go(1); if (DEMO[at].end) finish(b) } else if (d === 'prev') go(-1);
    else if (d === 'again') { at = 0; pop(); show(-1) } else if (d === 'full') setMode('full');
  });
  const setMode = m => {
    mode = m; pop(); $("#phReal").classList.toggle("demo", m === "demo"); $$('#modeSeg button').forEach(x => x.setAttribute('aria-selected', x.dataset.m === m));
    card.hidden = m !== 'demo'; $('#fullCopy').hidden = m === 'demo'; app.hidden = m !== 'demo';
    const f = $('iframe', scr); if (f) f.hidden = m === 'demo';
    $('#power').hidden = m === 'demo' || !!f;
  };
  if (!FULL) { liveEvents.paint = paintCard; show(); return }
  $('#modeSeg').addEventListener('click', e => { const b = e.target.closest('button'); if (b) setMode(b.dataset.m) });
  $('#powerBtn').addEventListener('click', () => { chime(); $('#power').hidden = true; load() });
  $('#realSeg').addEventListener('click', e => { const b = e.target.closest('button'); if (!b) return; view0 = b.dataset.v; $$('#realSeg button').forEach(x => x.setAttribute('aria-selected', x === b)); pop(); if ($('iframe', scr)) load() });
  liveEvents.paint = paintCard;
  show();
}

/* ================= founding-family waitlist ================= */
