  const cleanPhone = s => { let p = toLat(s).replace(/[\s\-().]/g, ''); if (/^\+98/.test(p)) p = '0' + p.slice(3); else if (/^0098/.test(p)) p = '0' + p.slice(4); else if (/^9\d{9}$/.test(p)) p = '0' + p; return p };
  const okPhone = p => /^09\d{9}$/.test(p) || /^\+\d{8,15}$/.test(p);
  const cleanCode = s => toLat(s).toUpperCase().replace(/[^A-Z0-9]/g, '').slice(0, 8);
  let refIn = ''; try { refIn = cleanCode(new URLSearchParams(location.search).get('ref')) } catch (e) { }
