  const genCode = () => { const A = 'ABCDEFGHJKMNPQRSTUVWXYZ23456789', r = new Uint8Array(6); if (window.crypto && crypto.getRandomValues) crypto.getRandomValues(r); else r.forEach((_, i) => r[i] = Math.random() * 255); return [...r].map(x => A[x % A.length]).join('') };
