/* ================= scroll choreography, depth and the section guide ================= */
// As each section scrolls in, its label, heading and text rise in order and the phone follows.
// While a phone is on screen it drifts a few pixels against the scroll (translate only, never rotated).
function motionInit() {
  const secs = $$('main > section');
  if (!RM) {
    document.documentElement.classList.add('mo');
    const io = new IntersectionObserver(es => es.forEach(en => { if (en.isIntersecting) { en.target.classList.add('seen'); io.unobserve(en.target) } }), { rootMargin: '0px 0px -12% 0px', threshold: .08 });
    secs.forEach(s => io.observe(s));
    const stages = $$('main > section:not(.hero) .stage, .duo');
    let tick = 0;
    const depth = () => { tick = 0; if (innerWidth < 900) { stages.forEach(s => s.style.removeProperty('--py')); return } const H = innerHeight;
      stages.forEach(s => { const r = s.getBoundingClientRect(); if (r.bottom < -100 || r.top > H + 100) return; const p = (r.top + r.height / 2 - H / 2) / H; s.style.setProperty('--py', (p * -28).toFixed(1) + 'px') }) };
    addEventListener('scroll', () => { if (!tick) tick = requestAnimationFrame(depth) }, { passive: true }); addEventListener('resize', depth); depth();
  }
  // the guide: one dot per section, named on hover, so parents always know where they are on a long page
  const rail = el('nav', 'rail'); rail.setAttribute('aria-label', 'sections'); document.body.appendChild(rail);
  const label = s => { const e = $('.eyebrow', s); return s.id === 'top' ? tx(['شروع', 'Start']) : e ? e.textContent.replace(/^\s*[۰-۹0-9]+\s*/, '').trim() : s.id };
  const paint = () => { rail.innerHTML = secs.map(s => `<a href="#${s.id}" data-r="${s.id}"><i></i><span>${label(s)}</span></a>`).join(''); mark() };
  let cur = 'top';
  const mark = () => $$('a', rail).forEach(a => a.classList.toggle('on', a.dataset.r === cur));
  const io2 = new IntersectionObserver(es => es.forEach(en => { if (en.isIntersecting) { cur = en.target.id; mark() } }), { rootMargin: '-45% 0px -50% 0px' });
  secs.forEach(s => io2.observe(s));
  rail.addEventListener('click', e => { const a = e.target.closest('a'); if (!a) return; e.preventDefault(); pop(); go(a.dataset.r) });
  // the nav condenses once the page moves, and every section ends with a clear way to the next one
  const navEl = $('#nav'), sc = () => navEl.classList.toggle('scrolled', scrollY > 16);
  addEventListener('scroll', sc, { passive: true }); sc();
  const cues = () => secs.forEach((s, i) => {
    const nx = secs[i + 1], w = $(':scope > .wrap', s); let c = $('.nextcue', s);
    if (!nx || !w || s.id === 'top') { if (c) c.remove(); return }
    if (!c) { c = el('div', 'nextcue'); w.appendChild(c) }
    c.innerHTML = `<a href="#${nx.id}"><span><small>${tx(['بعدی:', 'Next:'])}</small> ${label(nx)}</span><i>${ic('down', 18)}</i></a>`;
  });
  motionInit.paint = () => { paint(); cues() }; paint(); cues();
}

/* ================= boot ================= */
function repaintPhones() { paintHero(); patch('phAge', ageHtml()); patch('phMap', mapHtml()); patch('phAsk', askHtml()); patch('phFeel', feelHtml()); patch('phAbc', abcHtml()); if (!playing) patch('phWatch', watchHtml()); paintFamily(); patch('phCls', clsHtml()) }
