function boot() {
  bgInit(); paintIcons(); mountPhones();
  paintHero(); paintAge(); paintMap(); paintAsk(); paintFeel(); paintAbc(); paintWatch(); paintFamily(); paintPulse(); paintCls();
  heroEvents(); ageEvents(); mapEvents(); askEvents(); feelEvents(); abcEvents(); watchEvents(); familyEvents(); pulseEvents(); clsEvents(); closetEvents(); liveEvents();
  $('#pledges').addEventListener('click', e => { const p = e.target.closest('.pledge'); if (!p) return; p.classList.toggle('on'); if (p.classList.contains('on')) tone(520, .1, 'triangle', .05) });
  $('#hud').addEventListener('click', () => { pop(); journey() });
  $('#langBtn').addEventListener('click', () => { setLang(!L); pop() });
  const sb = $('#sndBtn'), paintSnd = () => { sb.innerHTML = ic(SND ? 'sound' : 'mute'); sb.setAttribute('aria-pressed', SND) };
  sb.addEventListener('click', () => { SND = !SND; store.set('snd', SND); paintSnd(); if (SND) chime() }); paintSnd();
  addEventListener('keydown', e => { if (e.key === 'Escape') { const s = $('.scrim'); if (s) s.remove() } });
  counters(); reveal(); navSpy(); setLang(L); J.refresh(); tourInit(); motionInit();
  G.done.forEach((d, i) => { if (d) { const t = $(`.try[data-try="${i}"]`); if (t) t.classList.add('done') } });
}
boot();

/* ================= design v3: creative layer =================
   Pointer light on cards, shapes orbiting the hero phone, Nazo riding the progress bar.
   All of it is decoration: nothing here is needed to read or use the page, and it stays off for reduced motion. */
(function creative() {
  const rm = matchMedia('(prefers-reduced-motion: reduce)').matches, fine = matchMedia('(hover:hover) and (pointer:fine)').matches;

  // Nazo rides the thin progress line under the nav as the page scrolls
  const nav = $('#nav .navprog');
  if (nav) {
    const r = el('span', 'ride'); r.setAttribute('aria-hidden', 'true'); r.innerHTML = nazo(G.color, G.wear, '');
    nav.appendChild(r);
    const upd = () => { const m = document.documentElement.scrollHeight - innerHeight, p = m > 0 ? Math.min(1, Math.max(0, scrollY / m)) : 0; r.style.setProperty('--p', p.toFixed(4)) };
    addEventListener('scroll', upd, { passive: true }); addEventListener('resize', upd); upd();
  }
  if (rm) return;

  // the app icon's four shapes orbit the hero phone and lean toward the pointer (translate only, no rotation of the phone)
  const hs = $('.herostage');
  if (hs) {
    const S = [
      ['green', '<path d="M4 4h56a56 56 0 0 1-56 56z" fill="#8CC63F"/>', -6, 6, 78],
      ['blue', '<path d="M60 4H4a56 56 0 0 0 56 56z" fill="#2D8ECF"/>', 4, 68, 64],
      ['orange', '<circle cx="30" cy="30" r="26" fill="#F4993A"/>', 78, 14, 46],
      ['red', '<circle cx="30" cy="30" r="26" fill="#EB4149"/>', 84, 74, 38]];
    S.forEach(([c, d, x, y, s], i) => {
      const o = el('span', 'orb ' + c); o.setAttribute('aria-hidden', 'true');
      o.style.cssText = `inset-inline-start:${x}%;top:${y}%;width:${s}px;height:${s}px;--d:${i * -3.1}s;--k:${(i % 2 ? -1 : 1) * (10 + i * 5)}`;
      o.innerHTML = `<svg viewBox="0 0 64 64">${d}</svg>`; hs.appendChild(o);
    });
    if (fine) {
      let raf = 0, tx = 0, ty = 0;
      addEventListener('pointermove', e => { tx = e.clientX / innerWidth - .5; ty = e.clientY / innerHeight - .5; if (!raf) raf = requestAnimationFrame(() => { raf = 0; hs.style.setProperty('--mx', tx.toFixed(3)); hs.style.setProperty('--my', ty.toFixed(3)) }) }, { passive: true });
    }
  }

  // a soft light follows the pointer across cards
  if (fine) {
    const SEL = '.lstep,.statbig,.pledge,.perks li,.dcard,.jcard,.agebox,.plan,.card';
    document.addEventListener('pointermove', e => {
      const c = e.target.closest && e.target.closest(SEL); if (!c || c.closest('.device')) return;
      const b = c.getBoundingClientRect(); c.style.setProperty('--lx', (e.clientX - b.left) + 'px'); c.style.setProperty('--ly', (e.clientY - b.top) + 'px'); c.classList.add('lit');
    }, { passive: true });
    document.addEventListener('pointerout', e => { const c = e.target.closest && e.target.closest(SEL); if (c) c.classList.remove('lit') }, { passive: true });
  }
})();

/* ================= design v3: motion pass 2 ================= */
(function motion2() {
  const rm = matchMedia('(prefers-reduced-motion: reduce)').matches;

  // nav: a single ink pill glides to whichever link is active
  const links = $('.links');
  if (links) {
    let ink = $('.ink', links); if (!ink) { ink = el('i', 'ink'); ink.setAttribute('aria-hidden', 'true'); links.prepend(ink) }
    // inline-start is the right edge in Persian, so measure from there
    const place2 = () => {
      const a = $('a.on', links); if (!a || !links.offsetWidth) { ink.style.setProperty('--o', 0); return }
      const rtl = document.documentElement.dir === 'rtl', x = rtl ? -(links.offsetWidth - a.offsetLeft - a.offsetWidth) : a.offsetLeft;
      ink.style.setProperty('--w', a.offsetWidth + 'px'); ink.style.setProperty('--x', x + 'px'); ink.style.setProperty('--o', 1);
    };
    new MutationObserver(place2).observe(links, { attributes: true, subtree: true, attributeFilter: ['class'] });
    if (window.ResizeObserver) { const ro = new ResizeObserver(place2); ro.observe(links); $$('a', links).forEach(a => ro.observe(a)) }
    addEventListener('resize', place2); setTimeout(place2, 300); document.fonts && document.fonts.ready.then(place2);
    $('#langBtn').addEventListener('click', () => { setTimeout(place2, 120); setTimeout(place2, 600) });
  }

  if (rm) return;
  // chapter numerals drift against the scroll
  const secs = $$('main > section[data-st]'); let t = 0;
  const run = () => { t = 0; const H = innerHeight; secs.forEach(s => { const r = s.getBoundingClientRect(); if (r.bottom < -200 || r.top > H + 200) return; s.style.setProperty('--ny', ((r.top + r.height / 2 - H / 2) * -.12).toFixed(1)) }) };
  addEventListener('scroll', () => { if (!t) t = requestAnimationFrame(run) }, { passive: true }); run();
})();

/* phones: note when the page is moving */
(function scrolling() {
  let t = 0; addEventListener('scroll', () => { document.body.classList.add('scrolling'); clearTimeout(t); t = setTimeout(() => document.body.classList.remove('scrolling'), 650) }, { passive: true });
})();

/* ================= design v3: something new on every swipe =================
   Delight thesis: scrolling Avanian should feel like walking Nazo's nine islands. Each stretch of the page
   hands the visitor something small to catch, watch or try, and the page notices them back.
   Nothing here blocks reading, nothing is required, and every flourish is skippable and silent unless sound is on. */
(function delight() {
  const rm = matchMedia('(prefers-reduced-motion: reduce)').matches;
  G.stars = Array.isArray(G.stars) ? G.stars : [];
  const IDS = ST.map(s => s.id), starsLeft = () => IDS.filter(id => !G.stars.includes(id));
  const STAR = '<svg viewBox="0 0 32 32" width="30" height="30" aria-hidden="true"><path d="M16 3l3.6 7.9 8.6 1-6.4 5.9 1.8 8.5L16 21.9 8.4 26.3l1.8-8.5L3.8 11.9l8.6-1z" fill="#FFD66E" stroke="#C9921B" stroke-width="1.6" stroke-linejoin="round"/><circle cx="12.4" cy="13" r="1.1" fill="#7A5200"/><circle cx="19.6" cy="13" r="1.1" fill="#7A5200"/></svg>';

  // 1. one hidden star on each island: a small find on every stretch of the page
  const place = () => IDS.forEach((id, i) => {
    const s = document.getElementById(id); if (!s || $('.star', s)) return;
    if (G.stars.includes(id)) return;
    const b = el('button', 'star', STAR); b.type = 'button'; b.dataset.s = id;
    b.setAttribute('aria-label', tx(['ستاره‌ی پنهان', 'Hidden star']));
    const x = 8 + ((i * 37 + 11) % 78); b.style.insetInlineStart = `calc(${x}% - 24px)`; b.style.top = (18 + ((i * 13) % 34)) + 'px'; b.style.setProperty('--d', (i * -.7) + 's');
    s.appendChild(b);
  });
  const found = async b => {
    const id = b.dataset.s; if (G.stars.includes(id)) return; G.stars.push(id); save();
    const r = b.getBoundingClientRect(); b.classList.add('got'); setTimeout(() => b.remove(), 700);
    if (navigator.vibrate && (!navigator.userActivation || navigator.userActivation.isActive)) try { navigator.vibrate(14) } catch (e) {}
    confetti(r.left + r.width / 2, r.top + r.height / 2, 18); tone(784, .1, 'triangle', .05); tone(1175, .16, 'sine', .04, .09);
    const n = G.stars.length, all = n === IDS.length;
    G.coins += all ? 50 : 5; save(); paintHud();
    const hud = $('#hud'); hud.classList.remove('bump'); void hud.offsetWidth; hud.classList.add('bump');
    toast(all ? tx(['همه‌ی ۹ ستاره را پیدا کردی! ۵۰ سکه‌ی هدیه', 'You found all 9 stars! 50 bonus coins']) : tx([`ستاره‌ی ${N(n)} از ${N(IDS.length)} پیدا شد. ۵ سکه`, `Star ${n} of ${IDS.length} found. 5 coins`]), 'coin');
    if (all) { chime(); [0, 250, 500].forEach(t => setTimeout(() => confetti(innerWidth * (.25 + Math.random() * .5), innerHeight * .4, 40), t)) }
  };
  document.addEventListener('click', e => { const b = e.target.closest && e.target.closest('.star'); if (b) { e.preventDefault(); found(b) } });
  place();

  // 2. "A day with Avanian": the five steps light up one after another, and any can be tapped
  const loop = $('#how .loop');
  if (loop && !rm) {
    const steps = $$('.lstep', loop); let i = -1, hold = 0, vis = false;
    const set = k => steps.forEach((s, j) => s.classList.toggle('act', j === k));
    new IntersectionObserver(es => { vis = es[0].isIntersecting }, { threshold: .3 }).observe(loop);
    setInterval(() => { if (!vis || document.hidden) return; if (hold > Date.now()) return; i = (i + 1) % steps.length; set(i) }, 2200);
    loop.addEventListener('click', e => { const s = e.target.closest('.lstep'); if (!s) return; i = steps.indexOf(s); set(i); hold = Date.now() + 7000; pop() });
  }

  // 3. the ribbon of what is inside: it drifts on its own and speeds up with the scroll
  const track = $('.band .track');
  if (track && !rm) {
    track.style.animation = 'none'; let pos = 0, last = scrollY, v = 0, vis = true, w = 0;
    new IntersectionObserver(es => { vis = es[0].isIntersecting }, { threshold: 0 }).observe($('.band'));
    const tick = () => {
      requestAnimationFrame(tick); if (!vis || document.hidden) return; if (!w) w = track.scrollWidth / 2; if (!w) return;
      const dv = scrollY - last; last = scrollY; v += (Math.min(40, Math.abs(dv)) - v) * .12;
      pos = (pos + .55 + v * .5) % w; const rtl = document.documentElement.dir === 'rtl';
      track.style.transform = `translate3d(${rtl ? pos : -pos}px,0,0)`;
    };
    addEventListener('resize', () => { w = 0 }); tick();
  }

  // 4. the hero greets the visitor by the time of day
  const cue = $('.hero .cue'), hr = new Date().getHours();
  if (cue) {
    const g = el('p', 'greet'); cue.before(g);
    const GREET = hr < 5 ? ['شب‌بخیر. این صفحه تا فردا همین‌جاست.', 'Good night. This page will be here tomorrow.']
      : hr < 12 ? ['صبح‌بخیر! یک بازی کوتاه، قبل از مدرسه.', 'Good morning! A short game before school.']
      : hr < 17 ? ['ظهر‌بخیر. بعد از ناهار، وقت یک بازی کوچک.', 'Good afternoon. A small game after lunch.']
      : hr < 21 ? ['عصر‌بخیر. مشق تمام شد؟ پس وقت بازی است.', 'Good evening. Homework done? Then it’s play time.']
      : ['شب‌بخیر. قبل از خواب، یک قصه‌ی آرام.', 'Good night. A quiet story before bed.'];
    const paint = () => { g.innerHTML = `${ic('sparkle', 18)}<span>${tx(GREET)}</span>` }; paint();
    $('#langBtn').addEventListener('click', () => setTimeout(paint, 60));
  }

  // 5. tap the logo five times and Nazo dances
  const logo = $('.logo'); let taps = 0, tt = 0;
  if (logo) logo.addEventListener('click', e => {
    taps++; clearTimeout(tt); tt = setTimeout(() => taps = 0, 1200);
    if (taps >= 5) {
      taps = 0; e.preventDefault(); const r = logo.getBoundingClientRect(); confetti(r.left + r.width / 2, r.bottom, 36); chime();
      logo.classList.remove('dance'); void logo.offsetWidth; logo.classList.add('dance'); setTimeout(() => logo.classList.remove('dance'), 1400);
      if (!G.egg) { G.egg = 1; save(); earn(10, logo, tx(['نازو رقصید! ۱۰ سکه', 'Nazo danced! 10 coins'])) } else toast(tx(['نازو دوباره رقصید', 'Nazo danced again']), 'smile');
    }
  });

  // 6. after a quiet half minute, Nazo peeks in and points to a star still hiding (twice per visit at most)
  let idle = 0, shown = 0, peek = null;
  const clearPeek = () => { if (peek) { peek.classList.remove('in'); const p = peek; peek = null; setTimeout(() => p.remove(), 500) } };
  const arm = () => {
    clearTimeout(idle); idle = setTimeout(() => {
      const left = starsLeft(); if (!left.length || shown >= 2 || document.body.classList.contains('touring') || $('.scrim')) return arm();
      shown++; const cur = IDS.map(id => document.getElementById(id)).filter(Boolean).find(s => s.getBoundingClientRect().bottom > innerHeight * .4) || null;
      const target = document.getElementById(left.find(id => cur && document.getElementById(id).offsetTop >= cur.offsetTop) || left[0]);
      peek = el('button', 'peek', `<span class="pz">${nazo(G.color, G.wear, 'joy')}</span><span class="pb">${tx(['یک ستاره این نزدیکی قایم شده. بیا پیدایش کنیم!', 'A star is hiding nearby. Let’s find it!'])}</span>`);
      peek.type = 'button'; document.body.appendChild(peek); requestAnimationFrame(() => peek && peek.classList.add('in'));
      peek.addEventListener('click', () => { clearPeek(); target && target.scrollIntoView({ behavior: rm ? 'auto' : 'smooth', block: 'start' }) });
      setTimeout(clearPeek, 9000);
    }, 30000);
  };
  ['pointerdown', 'keydown', 'wheel', 'touchstart'].forEach(ev => addEventListener(ev, () => { clearPeek(); arm() }, { passive: true })); arm();
  addEventListener('scroll', () => { clearTimeout(idle); arm() }, { passive: true });
})();
